def tema(id, titulo, porque, aspectos, repertorio):
    assert sum(p for _, p in aspectos) == 19, id
    return {"id": id, "titulo": titulo, "porque": porque, "aspectos": [{"t": t, "p": p} for t, p in aspectos], "repertorio": repertorio}

